"""W2c-1 (Punkt 150): Malaufträge der sechs Bögen im Zielstil (nur Zielstil-refs, genaue Beschreibung). Aufruf: python tools/w2c1_auftrag.py [endung] [namen,…] → entwurf/probe/stil/figuren/w2c1/auftrag<endung>.json, danach node tools/fal_bild.mjs …"""
import json, sys
v = sys.argv[1] if len(sys.argv) > 1 else ''
AW = ["ui-quelle/figuren/aschenwacht/reskin/aschenwacht_soldat_reskin.png", "ui-quelle/figuren/aschenwacht/reskin/aschenwacht_sturm_reskin.png", "ui-quelle/figuren/aschenwacht/reskin/aschenwacht_panzer_neu.png"]
KK = ["ui-quelle/figuren/konkordat/reskin/konkordat_soldat_reskin.png", "ui-quelle/figuren/konkordat/reskin/konkordat_sturm_reskin.png", "ui-quelle/figuren/konkordat/konkordat_fernsprech_neu.png"]
SAW = "soldiers of the same army as the references, in exactly their art style, proportions and armour (bulky men in riveted steel plate armour over ash-grey greatcoats, spiked helmets, gas masks with glowing yellow eyes, thick clean black ink outlines, hard comic shading, grime and blood spatter), all facing right"
SKK = "soldiers of the same army as the references, in exactly their art style, proportions and armour (bulky men in riveted steel plate armour over oxblood red greatcoats, brodie-style steel helmets, gas masks with glowing green eyes, thick clean black ink outlines, hard comic shading, grime and blood spatter), all facing right"
ENDE = " Wide empty gaps between all figures so that nothing touches, wide margin to all image edges. Flat solid magenta background (#FF00FF) everywhere, no ground, no cast shadows, no text. No skulls, no crosses, no eagles, no flags, no badges or plaques on helmets."
J = [
 ("aschenwacht_panzerbuechse_trupp", AW, "16:9", f"Draw a sheet with exactly THREE separate {SAW}, arranged in TWO rows. TOP ROW, alone: a gunner lying prone, holding a long anti-tank rifle on a small bipod with both hands, cheek on the stock; the rifle is part of this figure and appears only once on the whole sheet; the whole lying figure including boots fits completely inside the image. BOTTOM ROW, left: a loader kneeling, holding one large rifle cartridge in both hands. BOTTOM ROW, right: a spotter kneeling, looking through binoculars. No other weapons lying around, no extra figures."),
 ("konkordat_mg_trupp", KK, "16:9", f"Draw a sheet of exactly THREE separate groups of {SKK}, in one row: 1) LEFT: a HEAVY water-cooled machine gun with a thick ribbed cooling jacket, a water hose and a heavy low tripod, with a gunner sitting directly behind it, both hands on the grips, as one connected piece; the machine gun appears only once on the whole sheet and its muzzle stays well inside the image, far from the edge. 2) MIDDLE: a loader kneeling next to an open wooden ammunition box, holding an ammunition belt. 3) RIGHT: a spotter kneeling, looking through binoculars. No extra figures, no raised hands."),
 ("aschenwacht_mg_trupp", AW, "16:9", f"Draw a sheet of exactly THREE separate groups of {SAW}, in one row: 1) LEFT: a heavy water-cooled machine gun on a sled-type mount with a gunner kneeling directly behind it, both hands on the grips, as one connected piece; the machine gun appears only once on the whole sheet. 2) MIDDLE: a loader kneeling, holding an ammunition box and a belt of cartridges. 3) RIGHT: a spotter kneeling, looking through binoculars. No extra figures."),
 ("konkordat_moerser", KK, "4:3", f"Draw ONE single connected group of {SKK}: a heavy riveted trench mortar on a base plate with bipod, a crew member kneeling directly at the mortar aiming it with one hand on the elevation wheel, and a second crew member kneeling right beside it holding a mortar bomb ready to drop it into the barrel, a small open crate of mortar bombs touching the base plate. Mortar, crate and both men form one connected piece; the mortar appears only once."),
 ("aschenwacht_minenwerfer", AW, "4:3", f"Draw ONE single connected group of {SAW}: a heavy riveted short-barrelled trench mortar (minenwerfer) on a small two-wheeled carriage with a handwheel, one crew member loading a big finned bomb into the muzzle, a second crew member turning the handwheel on the other side, two spare bombs on a small stretcher beneath. Weapon, bombs and both men form one connected piece; the weapon appears only once. Nothing else in the picture: no vehicles, no tanks, no background objects."),
 ("konkordat_flammen", KK, "16:9", f"Draw a sheet of exactly FOUR separate {SKK}, each with a brass fuel tank backpack and a flame projector held in both hands, in one row: 1) advancing, projector held low; 2) standing and aiming the projector forward; 3) kneeling and aiming the projector forward; 4) walking, projector held at the hip. The four soldiers stand evenly spaced across the whole width with clearly visible empty magenta between every two of them. No flames coming out of the weapons, no extra figures."),
]
out = [{"name": f"{n}_w2c1{v}", "ordner": "entwurf/probe/stil/figuren/w2c1", "refs": r, "aspect": a, "res": "2K", "prompt": p + ENDE} for n, r, a, p in J]
only = sys.argv[2].split(',') if len(sys.argv) > 2 else None
if only: out = [o for o in out if any(o['name'].startswith(x) for x in only)]
json.dump(out, open(f'entwurf/probe/stil/figuren/w2c1/auftrag{v}.json', 'w', encoding='utf8'), ensure_ascii=False, indent=1); print(len(out), 'Aufträge')
